import React, { useState } from 'react';

export const MatrixInput: React.FC<MatrixInputProps> = ({
                                                            n, matrix, vector, onChange
                                                        }) => {
    const [expanded, setExpanded] = useState(false);
    const isLarge = n > 8;

    const toggleExpanded = () => setExpanded(!expanded);

    // Если матрица большая и не в развернутом режиме - показываем превью
    if (isLarge && !expanded) {
        return (
            <div className="space-y-4">
                <div className="bg-gray-50 p-4 rounded-lg border">
                    <div className="flex items-center justify-between mb-3">
                        <h3 className="font-medium">Матрица {n}×{n} (превью)</h3>
                        <button
                            onClick={toggleExpanded}
                            className="text-sm text-blue-600 hover:text-blue-800 flex items-center gap-1"
                        >
                            <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M4 8V4m0 0h4M4 4l5 5m11-1V4m0 0h-4m4 0l-5 5M4 16v4m0 0h4m-4 0l5-5m11 5l-5-5m5 5v-4m0 4h-4" />
                            </svg>
                            Развернуть для редактирования
                        </button>
                    </div>
                    <div className="grid grid-cols-4 gap-1">
                        {matrix.slice(0, 4).map((row, i) => (
                            <React.Fragment key={i}>
                                {row.slice(0, 4).map((val, j) => (
                                    <div key={j} className="bg-white p-2 text-center text-sm border rounded">
                                        {val.toFixed(2)}
                                    </div>
                                ))}
                                {row.length > 4 && <div className="col-span-1 text-center text-gray-400">...</div>}
                            </React.Fragment>
                        ))}
                        {matrix.length > 4 && (
                            <div className="col-span-4 text-center text-gray-400 text-sm py-2">
                                и еще {matrix.length - 4} строк...
                            </div>
                        )}
                    </div>
                </div>

                {/* Вектор всегда показываем полностью */}
                <div>
                    <label className="block text-sm font-medium text-gray-700 mb-2">
                        Вектор правой части b:
                    </label>
                    <div className="flex flex-wrap gap-2">
                        {vector.map((val, i) => (
                            <div key={i} className="flex items-center bg-white border rounded-md px-2 py-1">
                                <span className="text-xs text-gray-500 mr-1">b{i+1}=</span>
                                <input
                                    type="number"
                                    value={val === 0 ? '' : val}
                                    onChange={(e) => {
                                        const newVector = [...vector];
                                        newVector[i] = e.target.value === '' ? 0 : parseFloat(e.target.value) || 0;
                                        onChange(matrix, newVector);
                                    }}
                                    className="w-16 text-sm border-none focus:outline-none p-0"
                                    step="any"
                                />
                            </div>
                        ))}
                    </div>
                </div>
            </div>
        );
    }

    // Полный режим редактирования
    return (
        <div className="space-y-6">
            {isLarge && (
                <button
                    onClick={toggleExpanded}
                    className="text-sm text-blue-600 hover:text-blue-800 flex items-center gap-1 mb-2"
                >
                    <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                        <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M6 18L18 6M6 6l12 12" />
                    </svg>
                    Свернуть
                </button>
            )}

            <div>
                <label className="block text-sm font-medium text-gray-700 mb-3">
                    Матрица коэффициентов A:
                </label>
                <div className="overflow-x-auto pb-4 border rounded-lg p-4">
                    <div
                        className="grid gap-2"
                        style={{
                            gridTemplateColumns: `repeat(${n}, minmax(${n <= 10 ? '70px' : '60px'}, 1fr))`,
                            minWidth: n * 70 + 'px'
                        }}
                    >
                        {Array.from({ length: n }).map((_, i) =>
                            Array.from({ length: n }).map((_, j) => (
                                <input
                                    key={`a${i}${j}`}
                                    type="number"
                                    value={matrix[i]?.[j] === 0 ? '' : matrix[i]?.[j]}
                                    onChange={(e) => {
                                        const newMatrix = matrix.map(row => [...row]);
                                        newMatrix[i][j] = e.target.value === '' ? 0 : parseFloat(e.target.value) || 0;
                                        onChange(newMatrix, vector);
                                    }}
                                    className="w-full px-1 py-1 border border-gray-300 rounded-md focus:outline-none focus:ring-2 focus:ring-blue-500 text-center text-sm"
                                    step="any"
                                    placeholder={`a${i+1}${j+1}`}
                                />
                            ))
                        )}
                    </div>
                </div>
            </div>

            <div>
                <label className="block text-sm font-medium text-gray-700 mb-3">
                    Вектор правой части b:
                </label>
                <div className="overflow-x-auto pb-2 border rounded-lg p-4">
                    <div
                        className="grid gap-2"
                        style={{
                            gridTemplateColumns: `repeat(${n}, minmax(${n <= 10 ? '70px' : '60px'}, 1fr))`,
                            minWidth: n * 70 + 'px'
                        }}
                    >
                        {Array.from({ length: n }).map((_, i) => (
                            <input
                                key={`b${i}`}
                                type="number"
                                value={vector[i] === 0 ? '' : vector[i]}
                                onChange={(e) => {
                                    const newVector = [...vector];
                                    newVector[i] = e.target.value === '' ? 0 : parseFloat(e.target.value) || 0;
                                    onChange(matrix, newVector);
                                }}
                                className="w-full px-1 py-1 border border-gray-300 rounded-md focus:outline-none focus:ring-2 focus:ring-blue-500 text-center text-sm"
                                step="any"
                                placeholder={`b${i+1}`}
                            />
                        ))}
                    </div>
                </div>
            </div>
        </div>
    );
};
